var EDDA=window.EDDA=window.EDDA||{tools:{}};EDDA.tool=EDDA.tool||function(t){EDDA.tools[t.id]=t};
(function(){
var T=EDDA.tool;
function f(n,d){return EDDA.util.fmt(n,d)}
function m(n){return EDDA.util.money(n)}
function N(v){return EDDA.util.need.apply(null,arguments)}
function P(v,k){EDDA.util.pos(v,k)}

/* الحاسبة العادية */
function evalExpr(s){
 var i=0;s=s.replace(/\s+/g,'');
 function num(){var st=i;while(i<s.length&&/[0-9.]/.test(s[i]))i++;if(st===i)throw new Error('تعبير غير صالح');var t=s.slice(st,i);if((t.match(/\./g)||[]).length>1)throw new Error('رقم غير صالح');return parseFloat(t)}
 function factor(){var v;if(s[i]==='-'){i++;v=-factor()}else if(s[i]==='+'){i++;v=factor()}else if(s[i]==='('){i++;v=expr();if(s[i]!==')')throw new Error('قوس غير مغلق');i++}else v=num();while(s[i]==='%'){i++;v=v/100}return v}
 function term(){var v=factor();while(s[i]==='*'||s[i]==='/'){var o=s[i++];var r=factor();if(o==='*')v*=r;else{if(r===0)throw new Error('لا يمكن القسمة على صفر');v/=r}}return v}
 function expr(){var v=term();while(s[i]==='+'||s[i]==='-'){var o=s[i++];var r=term();v=o==='+'?v+r:v-r}return v}
 var r=expr();if(i<s.length)throw new Error('تعبير غير صالح');return r;
}
T({id:'basic-calculator',cat:'calc',title:'حاسبة عادية',desc:'حاسبة عادية مجانية للعمليات الأربع والنسبة والأقواس، تعمل بالنقر أو بلوحة المفاتيح.',kw:'حاسبة جمع طرح ضرب قسمة calculator',
 mount:function(root,ctx){
  root.innerHTML='<div class="calc"><div class="scr"><small id="cx"></small><b id="cr">0</b></div><div class="keys" id="ck"></div></div>';
  var keys=['C','⌫','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','±','0','.','='];var ck=root.querySelector('#ck'),cx=root.querySelector('#cx'),cr=root.querySelector('#cr');var ex='',done=false;
  keys.forEach(function(k){var b=document.createElement('button');b.type='button';b.textContent=k;if('÷×−+'.indexOf(k)>-1||k==='%')b.className='op';if(k==='=')b.className='eq';b.addEventListener('click',function(){press(k)});ck.appendChild(b)});
  function show(){cx.textContent=ex.replace(/\*/g,'×').replace(/\//g,'÷').replace(/-/g,'−');var r='';try{if(ex&&/[0-9)%]$/.test(ex)){r=evalExpr(ex);cr.textContent=f(r,10)}else cr.textContent=ex?cr.textContent:'0'}catch(e){}if(!ex)cr.textContent='0'}
  function press(k){
   if(k==='C'){ex='';done=false;return show()}
   if(k==='⌫'){ex=ex.slice(0,-1);return show()}
   if(k==='='){try{if(!ex)return;var r=evalExpr(ex);if(!isFinite(r))throw 0;ex=String(parseFloat(r.toPrecision(12)));done=true;cx.textContent='';cr.textContent=f(parseFloat(ex),10)}catch(e){cr.textContent=(e&&e.message)||'خطأ'}return}
   if(k==='±'){var mm=ex.match(/(-?[0-9.]+)$/);if(mm){ex=ex.slice(0,ex.length-mm[1].length)+(mm[1][0]==='-'?mm[1].slice(1):'-'+mm[1])}return show()}
   var ops={'÷':'/','×':'*','−':'-','+':'+','%':'%'};
   if(ops[k]){if(k==='%'){if(/[0-9)]$/.test(ex))ex+='%'}else{if(!ex&&k!=='−')return;if(/[+\-*/]$/.test(ex))ex=ex.slice(0,-1);ex+=ops[k]}done=false;return show()}
   if(done){ex='';done=false}
   if(k==='.'){var last=ex.split(/[+\-*/()%]/).pop();if(last.indexOf('.')>-1)return;if(!last)ex+='0'}
   ex+=k;show();
  }
  document.addEventListener('keydown',function(e){if(/INPUT|TEXTAREA|SELECT/.test((e.target.tagName||'')))return;var k=e.key;if(/[0-9.]/.test(k))press(k);else if(k==='+')press('+');else if(k==='-')press('−');else if(k==='*')press('×');else if(k==='/'){e.preventDefault();press('÷')}else if(k==='%')press('%');else if(k==='Enter'||k==='='){e.preventDefault();press('=')}else if(k==='Backspace')press('⌫');else if(k==='Escape'||k==='Delete')press('C')});
 },
 how:['اضغط على الأرقام والعمليات من الشاشة أو اكتبها بلوحة المفاتيح.','يظهر الناتج المبدئي تحت التعبير أثناء الكتابة.','اضغط «=» لتثبيت النتيجة، أو «C» للمسح و«⌫» لحذف آخر رقم.'],
 example:'اكتب 120+30×2 ثم اضغط «=». الناتج 180 لأن الضرب يُنفَّذ قبل الجمع. واكتب 200+10% لتحصل على 200.1 لأن 10% تُحسب كرقم 0.1.',
 about:'الحاسبة العادية أداة لإجراء العمليات الحسابية الأساسية: الجمع والطرح والضرب والقسمة، مع دعم النسبة المئوية كعدد عشري وتغيير الإشارة. تحترم الحاسبة أولوية العمليات الحسابية، فتنفّذ الضرب والقسمة قبل الجمع والطرح، وتعمل بالكامل داخل متصفحك دون إرسال أي بيانات.',
 when:'عندما تحتاج حسابًا سريعًا دون فتح تطبيق الهاتف: مراجعة فاتورة، جمع مصاريف، أو التحقق من رقم أثناء العمل على الكمبيوتر. ولحسابات أكثر تخصصًا استخدم حاسبة النسبة المئوية أو الخصم.',
 faqs:[['هل تحترم الحاسبة أولوية العمليات؟','نعم. الضرب والقسمة يُحسبان قبل الجمع والطرح، فالتعبير 2+3×4 يساوي 14.'],['كيف تعمل علامة النسبة؟','علامة % تقسم الرقم الذي قبلها على 100، فـ 50% تساوي 0.5. لحساب نسبة من رقم اكتب مثلًا 200×15%.'],['هل أستطيع استخدام لوحة المفاتيح؟','نعم، تعمل الأرقام والعمليات وEnter وBackspace وEscape عندما لا يكون مؤشر الكتابة داخل حقل آخر.']],related:['percentage-calculator','discount-calculator']});

/* النسبة المئوية */
T({id:'percentage-calculator',cat:'calc',title:'حاسبة النسبة المئوية',desc:'احسب النسبة المئوية بثلاث طرق: كم تساوي نسبة من رقم، كم يمثل رقم من آخر، ونسبة التغير بينهما.',kw:'نسبة مئوية percent حساب النسبة',
 fields:[{id:'a',label:'العدد الأول (أ)',type:'number',ph:'مثال: 15'},{id:'b',label:'العدد الثاني (ب)',type:'number',ph:'مثال: 200'}],ex:{a:15,b:200},btn:'احسب النسبة',live:true,
 run:function(v){N(v,'a','b');var r=[['أ% من ب (أ ÷ 100 × ب)',f(v.a/100*v.b,4),1]];r.push(['أ تمثل كم % من ب',v.b===0?'غير معرّف (ب = 0)':f(v.a/v.b*100,4)+'%']);r.push(['نسبة التغير من أ إلى ب',v.a===0?'غير معرّف (أ = 0)':f((v.b-v.a)/Math.abs(v.a)*100,4)+'%']);r.push(['ب بعد زيادة أ%',f(v.b*(1+v.a/100),4)]);r.push(['ب بعد نقص أ%',f(v.b*(1-v.a/100),4)]);return {rows:r}},
 how:['أدخل العدد الأول (أ) والعدد الثاني (ب).','تظهر النتائج فورًا: النسبة من الرقم، والتمثيل، ونسبة التغير.','استخدم زر النسخ لنقل النتيجة.'],
 example:'إذا أدخلت أ = 15 وب = 200 فإن 15% من 200 تساوي 30، والرقم 15 يمثل 7.5% من 200.',
 about:'حاسبة النسبة المئوية تجيب عن الأسئلة الثلاثة الأكثر شيوعًا: كم تساوي نسبة معينة من رقم، وكم تمثل نسبة رقم من آخر، وما نسبة التغير (زيادة أو نقصان) بين قيمتين. تعتمد على القانون: النسبة = الجزء ÷ الكل × 100.',
 when:'عند حساب خصم أو زيادة سعر، أو درجة طالب من مجموع، أو نسبة نمو المبيعات بين شهرين، أو أي مقارنة بين رقمين.',
 faqs:[['كيف أحسب 15% من 200؟','اضرب 200 في 15 ثم اقسم على 100، فالناتج 30. الأداة تعرض لك هذه النتيجة تلقائيًا.'],['كيف أحسب نسبة الزيادة؟','نسبة التغير = (القيمة الجديدة − القيمة القديمة) ÷ القيمة القديمة × 100. أدخل القديمة في (أ) والجديدة في (ب).'],['لماذا تظهر «غير معرّف»؟','لأن القسمة على صفر غير ممكنة رياضيًا.']],related:['discount-calculator','increase-decrease-calculator','vat-calculator']});

/* الخصم */
T({id:'discount-calculator',cat:'calc',title:'حاسبة الخصم',desc:'احسب قيمة الخصم والمبلغ الذي توفره والسعر النهائي من السعر الأصلي ونسبة الخصم.',kw:'خصم تخفيض sale discount',
 fields:[{id:'price',label:'السعر الأصلي',type:'number',ph:'مثال: 1500'},{id:'pct',label:'نسبة الخصم %',type:'number',ph:'مثال: 20'}],ex:{price:1500,pct:20},live:true,
 run:function(v){N(v,'price','pct');P(v,'price');if(v.pct>100)throw new Error('نسبة الخصم لا يمكن أن تتجاوز 100%');var d=v.price*v.pct/100;return {rows:[['قيمة الخصم',m(d)],['السعر بعد الخصم',m(v.price-d),1],['نسبة ما تدفعه',f(100-v.pct,2)+'%']]}},
 how:['اكتب السعر الأصلي للمنتج.','اكتب نسبة الخصم المعلنة.','سترى قيمة الخصم والسعر النهائي فورًا.'],
 example:'منتج بسعر 1500 عليه خصم 20% يكون الخصم 300 والسعر النهائي 1200.',
 about:'حاسبة الخصم تحسب قيمة التخفيض من السعر الأصلي ونسبة الخصم، وتعطيك السعر النهائي وما توفّره. المعادلة: قيمة الخصم = السعر × النسبة ÷ 100.',
 when:'أثناء التسوق في العروض والتخفيضات، أو عند وضع عروض لعملائك كتاجر وتريد معرفة السعر النهائي بدقة.',
 faqs:[['كيف أعرف السعر بعد الخصم؟','اطرح قيمة الخصم من السعر الأصلي، أو اضرب السعر في (100 − نسبة الخصم) ثم اقسم على 100.'],['هل يمكن أن يزيد الخصم عن 100%؟','لا، الخصم 100% يعني أن المنتج مجاني، وأكثر منه غير منطقي.'],['كيف أحسب خصمين متتاليين؟','استخدم أداة «حساب السعر بعد الخصم» التي تدعم خصمًا ثانيًا.']],related:['price-after-discount','percentage-calculator','vat-calculator']});

T({id:'price-after-discount',cat:'calc',title:'حساب السعر بعد الخصم',desc:'اعرف السعر النهائي بعد خصم أول وخصم ثانٍ اختياري وخصم بمبلغ ثابت، مع إجمالي ما وفّرته.',kw:'سعر بعد الخصم خصمين متتاليين كوبون',
 fields:[{id:'price',label:'السعر الأصلي',type:'number',ph:'مثال: 2000'},{id:'d1',label:'الخصم الأول %',type:'number',ph:'مثال: 10'},{id:'d2',label:'خصم ثانٍ % (اختياري)',type:'number',ph:'مثال: 5'},{id:'fix',label:'خصم بمبلغ ثابت (اختياري)',type:'number',ph:'مثال: 50',hint:'مثل كوبون بقيمة محددة، يُخصم بعد النسب.'}],ex:{price:2000,d1:10,d2:5,fix:50},
 run:function(v){N(v,'price');P(v,'price');var d1=v.d1||0,d2=v.d2||0,fx=v.fix||0;if(d1>100||d2>100||d1<0||d2<0)throw new Error('نسب الخصم يجب أن تكون بين 0 و100');var a=v.price*(1-d1/100);var b=a*(1-d2/100);var c=Math.max(0,b-fx);var tot=v.price-c;return {rows:[['بعد الخصم الأول',m(a)],['بعد الخصم الثاني',m(b)],['السعر النهائي',m(c),1],['إجمالي ما وفّرته',m(tot)],['نسبة التوفير الكلية',f(v.price?tot/v.price*100:0,2)+'%']],note:'الخصمان بالنسبة يُحسبان بالتتابع، فالثاني يُطبق على السعر بعد الأول وليس على السعر الأصلي.'}},
 how:['أدخل السعر الأصلي.','أدخل الخصم الأول، ثم الثاني إن وُجد، ثم أي خصم بمبلغ ثابت.','اضغط «احسب» لترى السعر النهائي وإجمالي التوفير.'],
 example:'سعر 2000 مع خصم 10% ثم 5% وكوبون 50: بعد الأول 1800، بعد الثاني 1710، والنهائي 1660.',
 about:'تحسب هذه الأداة السعر النهائي عند وجود أكثر من خصم. خصمان 10% و5% لا يساويان 15% لأن الثاني يُحسب على المبلغ المتبقي. تعرض الأداة كل خطوة لتتأكد من الحساب.',
 when:'عندما يجتمع خصم المتجر مع خصم إضافي للبطاقة أو كوبون، وتريد معرفة ما ستدفعه فعلًا قبل الشراء.',
 faqs:[['هل خصم 10% ثم 5% يساوي خصم 15%؟','لا. الخصم الكلي الفعلي هنا 14.5% لأن الخصم الثاني يُطبَّق على السعر بعد الأول.'],['هل يُخصم الكوبون قبل النسبة أم بعدها؟','تفترض الأداة أن المبلغ الثابت يُخصم بعد النسب. اقرأ شروط العرض لأن بعض المتاجر تعكس الترتيب.'],['هل السعر النهائي قد يكون سالبًا؟','لا، تتوقف الأداة عند صفر.']],related:['discount-calculator','vat-calculator']});

/* هامش الربح في الحسابات يُعرّف في التجارة، مع also */
T({id:'buy-sell-difference',cat:'calc',title:'حساب الفرق بين سعر الشراء والبيع',desc:'احسب الفرق بين سعر الشراء وسعر البيع، ونسبته من الشراء ومن البيع، وإجمالي الربح أو الخسارة للكمية.',kw:'فرق سعر الشراء والبيع ربح خسارة',
 fields:[{id:'buy',label:'سعر الشراء (للوحدة)',type:'number',ph:'مثال: 80'},{id:'sell',label:'سعر البيع (للوحدة)',type:'number',ph:'مثال: 100'},{id:'qty',label:'الكمية',type:'number',def:1}],ex:{buy:80,sell:100,qty:10},
 run:function(v){N(v,'buy','sell','qty');P(v,'buy');P(v,'sell');var d=v.sell-v.buy;var tot=d*v.qty;return {rows:[[d>=0?'الربح للوحدة':'الخسارة للوحدة',m(Math.abs(d))],['النسبة من سعر الشراء',v.buy?f(d/v.buy*100,2)+'%':'—'],['النسبة من سعر البيع',v.sell?f(d/v.sell*100,2)+'%':'—'],[tot>=0?'إجمالي الربح':'إجمالي الخسارة',m(Math.abs(tot)),1]]}},
 how:['أدخل سعر الشراء وسعر البيع للوحدة.','أدخل الكمية (اتركها 1 للوحدة الواحدة).','اضغط «احسب» لرؤية الفرق والنسبتين والإجمالي.'],
 example:'شراء بـ 80 وبيع بـ 100 لعشر وحدات: الربح للوحدة 20 (25% من الشراء، 20% من البيع) والإجمالي 200.',
 about:'تُظهر الأداة الفرق بين ما دفعته وما بعت به، وتعطيك النسبة من الشراء (المكسب) ومن البيع (الهامش). الفرق بين النسبتين مصدر ارتباك شائع، لذا نعرضهما معًا.',
 when:'لتقييم صفقة بيع وشراء، أو مراجعة ربح سلعة أعدت بيعها، أو مقارنة عرضين.',
 faqs:[['ما الفرق بين المكسب والهامش؟','المكسب نسبة الربح من سعر الشراء، والهامش نسبته من سعر البيع. شراء بـ 80 وبيع بـ 100: المكسب 25% والهامش 20%.'],['ماذا يعني الناتج السالب؟','أنك بعت بأقل من سعر الشراء، وتُعرض القيمة كخسارة.'],['هل تدخل المصاريف الأخرى؟','لا، لحسابها استخدم «حاسبة الأرباح التجارية».']],related:['trade-profit-calculator','profit-margin-calculator','profit-percentage-calculator']});

T({id:'trade-profit-calculator',cat:'calc',title:'حاسبة الأرباح التجارية',desc:'احسب صافي ربح صفقة تجارية بعد خصم تكلفة الشراء والمصاريف، مع هامش الربح وعائد الاستثمار.',kw:'ربح تجاري صافي الربح عائد ROI تجارة',
 fields:[{id:'buy',label:'سعر شراء الوحدة',type:'number',ph:'مثال: 50'},{id:'sell',label:'سعر بيع الوحدة',type:'number',ph:'مثال: 75'},{id:'qty',label:'الكمية',type:'number',ph:'مثال: 100'},{id:'exp',label:'مصاريف أخرى إجمالية (شحن، إيجار...)',type:'number',def:0}],ex:{buy:50,sell:75,qty:100,exp:800},
 run:function(v){N(v,'buy','sell','qty');P(v,'buy');P(v,'sell');P(v,'qty');var e=v.exp||0;var rev=v.sell*v.qty,cost=v.buy*v.qty+e,net=rev-cost;return {rows:[['إجمالي المبيعات',m(rev)],['إجمالي التكلفة (شراء + مصاريف)',m(cost)],[net>=0?'صافي الربح':'صافي الخسارة',m(Math.abs(net)),1],['هامش الربح (من المبيعات)',rev?f(net/rev*100,2)+'%':'—'],['عائد الاستثمار ROI (من التكلفة)',cost?f(net/cost*100,2)+'%':'—'],['الربح للوحدة بعد المصاريف',v.qty?m(net/v.qty):'—']]}},
 how:['أدخل سعر شراء وبيع الوحدة والكمية.','أضف إجمالي المصاريف الأخرى مثل الشحن والإيجار.','اضغط «احسب» لتحصل على صافي الربح والنسب.'],
 example:'شراء 100 وحدة بـ 50 وبيعها بـ 75 مع مصاريف 800: المبيعات 7500، التكلفة 5800، وصافي الربح 1700.',
 about:'تحسب هذه الأداة صافي ربح الصفقة بعد كل التكاليف، وتعرض هامش الربح (من المبيعات) وعائد الاستثمار ROI (من التكلفة)، وهما مؤشران أساسيان لقياس نجاح أي صفقة.',
 when:'قبل شراء بضاعة بالجملة لإعادة بيعها، أو عند مراجعة نتيجة موسم مبيعات.',
 faqs:[['ما هو ROI؟','نسبة صافي الربح إلى إجمالي ما أنفقته. ROI 29% يعني أن كل 100 أنفقتها أعادت لك 29 ربحًا.'],['هل أضيف ثمن الشحن؟','نعم، أضفه في المصاريف الأخرى حتى يعكس الربح الحقيقي.'],['هل تُحسب الضرائب؟','لا، أضف قيمة الضريبة المتوقعة ضمن المصاريف إن أردت.']],related:['buy-sell-difference','profit-margin-calculator','small-business-profit-calculator']});

/* الأقساط */
T({id:'installment-calculator',cat:'calc',title:'حاسبة الأقساط',desc:'احسب القسط الشهري وإجمالي الفائدة والمبلغ الكلي لأي سلعة أو قرض بفائدة تناقصية أو ثابتة.',kw:'أقساط قرض تقسيط فائدة قسط شهري',
 fields:[{id:'price',label:'سعر السلعة أو مبلغ القرض',type:'number',ph:'مثال: 60000'},{id:'down',label:'المقدم',type:'number',def:0},{id:'months',label:'عدد الأشهر',type:'number',ph:'مثال: 24'},{id:'rate',label:'نسبة الفائدة السنوية %',type:'number',def:0},{id:'kind',label:'نوع الفائدة',type:'select',options:[['reducing','تناقصية (على الرصيد المتبقي)'],['flat','ثابتة (على أصل المبلغ)']],def:'reducing'}],ex:{price:60000,down:10000,months:24,rate:18,kind:'reducing'},
 run:function(v){N(v,'price','months');P(v,'price');var down=v.down||0,rate=v.rate||0;if(down>=v.price)throw new Error('المقدم يجب أن يكون أقل من السعر');if(v.months<1||Math.round(v.months)!==v.months)throw new Error('عدد الأشهر يجب أن يكون رقمًا صحيحًا موجبًا');var p=v.price-down,n=v.months,pay,tot;if(v.kind==='flat'){var intr=p*rate/100*(n/12);tot=p+intr;pay=tot/n}else{var i=rate/1200;pay=i===0?p/n:p*i/(1-Math.pow(1+i,-n));tot=pay*n}return {rows:[['المبلغ الممول',m(p)],['القسط الشهري',m(pay),1],['إجمالي المدفوع بالأقساط',m(tot)],['إجمالي الفائدة',m(tot-p)],['إجمالي ما ستدفعه مع المقدم',m(tot+down)]],note:'النتيجة تقريبية. قد تضيف الجهة الممولة رسومًا إدارية أو تأمينًا لا تدخل في هذا الحساب.'}},
 how:['أدخل سعر السلعة والمقدم (إن وُجد).','حدد عدد الأشهر والفائدة السنوية ونوعها.','اضغط «احسب» لتعرف القسط الشهري والإجمالي.'],
 example:'سلعة بـ 60000 ومقدم 10000 على 24 شهرًا بفائدة تناقصية 18% سنويًا: القسط حوالي 2496 شهريًا.',
 about:'تحسب الأداة القسط الشهري بطريقتين: الفائدة التناقصية التي تُحسب على الرصيد المتبقي (الأكثر شيوعًا في القروض البنكية) والفائدة الثابتة التي تُحسب على أصل المبلغ طوال المدة. وإذا كانت الفائدة صفرًا فالقسط هو المبلغ مقسومًا على عدد الأشهر.',
 when:'قبل شراء سيارة أو جهاز أو أثاث بالتقسيط، أو عند المقارنة بين عروض تمويل مختلفة.',
 faqs:[['ما الفرق بين الفائدة التناقصية والثابتة؟','في التناقصية تقل الفائدة مع سداد الأقساط، وفي الثابتة تُحسب على كامل المبلغ طوال المدة فيكون إجمالي الفائدة أكبر عادة لنفس النسبة.'],['هل الناتج هو الرقم النهائي من البنك؟','لا، هو تقدير. قد توجد رسوم وتأمين وعمولات.'],['ماذا لو لا توجد فائدة؟','اترك الفائدة 0 وسيكون القسط = (السعر − المقدم) ÷ عدد الأشهر.']],related:['savings-calculator','financial-goal-calculator']});

T({id:'savings-calculator',cat:'calc',title:'حاسبة الادخار',desc:'اعرف كم سيصبح رصيدك بعد مدة من الادخار الشهري مع عائد سنوي مركّب، وكم منه إيداعات وكم أرباح.',kw:'ادخار توفير فائدة مركبة وديعة savings',
 fields:[{id:'init',label:'المبلغ الابتدائي',type:'number',def:0},{id:'monthly',label:'الادخار الشهري',type:'number',ph:'مثال: 1000'},{id:'rate',label:'العائد السنوي المتوقع %',type:'number',def:0},{id:'years',label:'المدة بالسنوات',type:'number',ph:'مثال: 5'}],ex:{init:5000,monthly:1000,rate:10,years:5},
 run:function(v){N(v,'monthly','years');P(v,'monthly');P(v,'years');var init=v.init||0,r=(v.rate||0)/1200,n=Math.round(v.years*12);if(n<1)throw new Error('المدة قصيرة جدًا');var g=Math.pow(1+r,n);var fv=r===0?init+v.monthly*n:init*g+v.monthly*(g-1)/r;var dep=init+v.monthly*n;return {rows:[['الرصيد النهائي المتوقع',m(fv),1],['إجمالي ما أودعته',m(dep)],['إجمالي الأرباح',m(fv-dep)],['عدد الأشهر',String(n)]],note:'يفترض الحساب عائدًا ثابتًا يُضاف شهريًا وإيداعًا في نهاية كل شهر. العوائد الفعلية قد تختلف وليست مضمونة.'}},
 how:['أدخل المبلغ الابتدائي إن وُجد.','أدخل المبلغ الذي تدّخره كل شهر والعائد السنوي المتوقع.','أدخل المدة واضغط «احسب».'],
 example:'مبلغ ابتدائي 5000 وادخار 1000 شهريًا بعائد 10% لمدة 5 سنوات: الرصيد حوالي 83,000 منها 65,000 إيداعات.',
 about:'تحسب هذه الأداة نمو مدخراتك مع الفائدة المركّبة شهريًا. الفائدة المركبة تعني أن الأرباح نفسها تُنتج أرباحًا لاحقًا، وهذا ما يجعل المدة الطويلة أكثر تأثيرًا.',
 when:'عند التخطيط لوديعة أو شهادة ادخار، أو لتقدير ما ستجمعه من ادخار شهري ثابت خلال سنوات.',
 faqs:[['هل العائد مضمون؟','لا. الأداة تحسب سيناريو بعائد ثابت تدخله أنت، والعوائد الفعلية تتغير.'],['كيف يُحسب العائد؟','يُقسم العائد السنوي على 12 ويُضاف كل شهر على الرصيد.'],['ماذا لو لم أضف مبلغًا شهريًا؟','أدخل 0 وستحصل على نمو المبلغ الابتدائي فقط.']],related:['financial-goal-calculator','installment-calculator']});

T({id:'financial-goal-calculator',cat:'calc',title:'حساب الأهداف المالية',desc:'اعرف كم تدّخر شهريًا لتصل إلى هدف مالي معين خلال مدة محددة، مع احتساب عائد اختياري.',kw:'هدف مالي توفير شراء سيارة زواج تخطيط',
 fields:[{id:'goal',label:'المبلغ المستهدف',type:'number',ph:'مثال: 200000'},{id:'cur',label:'ما تملكه حاليًا',type:'number',def:0},{id:'months',label:'المدة بالأشهر',type:'number',ph:'مثال: 24'},{id:'rate',label:'العائد السنوي المتوقع %',type:'number',def:0}],ex:{goal:200000,cur:20000,months:24,rate:8},
 run:function(v){N(v,'goal','months');P(v,'goal');var cur=v.cur||0,r=(v.rate||0)/1200,n=Math.round(v.months);if(n<1)throw new Error('المدة يجب أن تكون شهرًا واحدًا على الأقل');var g=Math.pow(1+r,n);var need=r===0?(v.goal-cur)/n:(v.goal-cur*g)*r/(g-1);if(need<=0)return {rows:[['النتيجة','ستحقق هدفك بدون ادخار إضافي',1],['قيمة ما تملكه عند نهاية المدة',m(cur*g)]]};return {rows:[['المبلغ المطلوب ادخاره شهريًا',m(need),1],['إجمالي ما ستودعه',m(need*n)],['الأرباح المتوقعة',m(v.goal-cur-need*n)],['المدة بالسنوات',f(n/12,1)]],note:'تقدير يفترض عائدًا ثابتًا وإيداعًا في نهاية كل شهر.'}},
 how:['أدخل المبلغ الذي تريد الوصول إليه وما تملكه الآن.','حدد المدة بالأشهر والعائد المتوقع إن أردت.','اضغط «احسب» لتعرف مبلغ الادخار الشهري.'],
 example:'هدف 200000 خلال 24 شهرًا ومعك 20000 وعائد 8%: تحتاج إلى ادخار حوالي 7,000 شهريًا.',
 about:'تحوّل هذه الأداة الهدف المالي إلى رقم واضح تدّخره كل شهر. تأخذ في الحسبان ما تملكه الآن والعائد المتوقع، لتعرف إن كان هدفك واقعيًا خلال المدة التي حددتها.',
 when:'عند التخطيط لشراء سيارة أو شقة أو تجهيز زواج أو رحلة أو مصروفات دراسة.',
 faqs:[['ماذا لو كان الناتج كبيرًا جدًا؟','زِد المدة أو قلّل المبلغ المستهدف أو ابحث عن مصدر إضافي للدخل.'],['هل أحتاج إلى إدخال عائد؟','لا، اتركه 0 لحساب الادخار البسيط.'],['هل التضخم محسوب؟','لا، قد ترتفع الأسعار مستقبلًا، فضع هدفًا أعلى قليلًا.']],related:['savings-calculator','installment-calculator']});

T({id:'vat-calculator',cat:'calc',title:'حاسبة السعر قبل الضريبة وبعدها',desc:'أضف ضريبة القيمة المضافة إلى سعر، أو استخرج السعر قبل الضريبة من سعر شامل، مع قيمة الضريبة.',kw:'ضريبة قيمة مضافة vat tax سعر شامل',
 fields:[{id:'amount',label:'المبلغ',type:'number',ph:'مثال: 1000'},{id:'rate',label:'نسبة الضريبة %',type:'number',def:14,hint:'غيّر النسبة حسب بلدك وحسب نوع السلعة.'},{id:'mode',label:'ماذا تريد؟',type:'select',options:[['add','إضافة الضريبة (المبلغ قبل الضريبة)'],['remove','استخراج السعر قبل الضريبة (المبلغ شامل)']],def:'add'}],ex:{amount:1000,rate:14,mode:'add'},
 run:function(v){N(v,'amount','rate');P(v,'amount');P(v,'rate');var a=v.amount,r=v.rate/100;if(v.mode==='add')return {rows:[['السعر قبل الضريبة',m(a)],['قيمة الضريبة',m(a*r)],['السعر بعد الضريبة',m(a*(1+r)),1]]};var b=a/(1+r);return {rows:[['السعر الشامل',m(a)],['السعر قبل الضريبة',m(b),1],['قيمة الضريبة',m(a-b)]]}},
 how:['أدخل المبلغ ونسبة الضريبة المطبقة.','اختر هل المبلغ قبل الضريبة أم شامل لها.','اضغط «احسب» لتظهر قيمة الضريبة والسعر المقابل.'],
 example:'سعر 1000 قبل الضريبة بنسبة 14% يصبح 1140 بعد الضريبة. وسعر شامل 1140 يعود إلى 1000 قبل الضريبة.',
 about:'ضريبة القيمة المضافة نسبة تُضاف إلى سعر السلعة أو الخدمة. تحسب الأداة الاتجاهين: إضافة الضريبة إلى سعر خالٍ منها، أو استخراج السعر الأصلي من سعر شامل. لاستخراج السعر الأصلي نقسم على (1 + النسبة) وليس نطرح النسبة مباشرة.',
 when:'عند إعداد فاتورة، أو مراجعة سعر شامل وتريد معرفة الضريبة فيه، أو التسعير لعملاء من دول بنسب مختلفة.',
 faqs:[['لماذا لا أطرح 14% من السعر الشامل؟','لأن الضريبة محسوبة على السعر الأصلي. السعر الأصلي = السعر الشامل ÷ 1.14، وليس 86% منه.'],['ما النسبة الصحيحة في بلدي؟','تختلف من بلد لآخر وحسب السلعة. تحقق من الجهة الضريبية الرسمية. الأداة تعتمد النسبة التي تدخلها.'],['هل الأداة بديل عن محاسب؟','لا، هي للتقدير السريع.']],related:['percentage-calculator','order-total-calculator','discount-calculator']});

T({id:'increase-decrease-calculator',cat:'calc',title:'حاسبة الزيادة والنقصان',desc:'احسب القيمة الجديدة بعد زيادة أو نقصان بنسبة مئوية، ومقدار التغير.',kw:'زيادة نقصان نسبة زيادة سعر راتب علاوة',
 fields:[{id:'val',label:'القيمة الأصلية',type:'number',ph:'مثال: 5000'},{id:'pct',label:'النسبة %',type:'number',ph:'مثال: 12'},{id:'dir',label:'نوع التغير',type:'select',options:[['up','زيادة'],['down','نقصان']],def:'up'}],ex:{val:5000,pct:12,dir:'up'},live:true,
 run:function(v){N(v,'val','pct');var d=v.val*v.pct/100;var nv=v.dir==='up'?v.val+d:v.val-d;return {rows:[['مقدار '+(v.dir==='up'?'الزيادة':'النقصان'),m(d)],['القيمة الجديدة',m(nv),1],['للرجوع إلى القيمة الأصلية تحتاج تغيرًا بنسبة',nv?f(Math.abs((v.val-nv)/nv*100),2)+'%':'—']]}},
 how:['أدخل القيمة الأصلية.','أدخل النسبة واختر زيادة أو نقصان.','تظهر القيمة الجديدة ومقدار التغير فورًا.'],
 example:'راتب 5000 بعد علاوة 12% يصبح 5600. ولو نقص بنفس النسبة يصبح 4400.',
 about:'تحسب الأداة القيمة بعد تطبيق زيادة أو نقصان بنسبة مئوية. وتوضح أيضًا أن الزيادة بنسبة ثم النقصان بنفس النسبة لا يرجعان الرقم إلى أصله، لأن النسبة تُحسب كل مرة على قيمة مختلفة.',
 when:'عند حساب علاوة الراتب، أو ارتفاع الأسعار، أو انخفاض المبيعات، أو تعديل ميزانية بنسبة معينة.',
 faqs:[['لماذا لا تعود القيمة لأصلها بعد زيادة ونقصان بنفس النسبة؟','لأن النسبة الثانية تُحسب على قيمة أكبر أو أصغر. زيادة 20% ثم نقصان 20% تعطي 96% من الأصل.'],['كيف أحسب نسبة الزيادة بين رقمين؟','استخدم حاسبة النسبة المئوية وأدخل الرقمين لتحصل على نسبة التغير.']],related:['percentage-calculator','discount-calculator']});

/* تحويل العملات */
var CURS=[['EGP','الجنيه المصري'],['USD','الدولار الأمريكي'],['EUR','اليورو'],['GBP','الجنيه الإسترليني'],['SAR','الريال السعودي'],['AED','الدرهم الإماراتي'],['KWD','الدينار الكويتي'],['QAR','الريال القطري'],['BHD','الدينار البحريني'],['OMR','الريال العماني'],['JOD','الدينار الأردني'],['IQD','الدينار العراقي'],['LBP','الليرة اللبنانية'],['SYP','الليرة السورية'],['MAD','الدرهم المغربي'],['DZD','الدينار الجزائري'],['TND','الدينار التونسي'],['LYD','الدينار الليبي'],['SDG','الجنيه السوداني'],['TRY','الليرة التركية'],['JPY','الين الياباني'],['CNY','اليوان الصيني'],['INR','الروبية الهندية'],['CAD','الدولار الكندي'],['AUD','الدولار الأسترالي'],['CHF','الفرنك السويسري'],['RUB','الروبل الروسي'],['PKR','الروبية الباكستانية']];
var ratesCache=null;
function loadRates(){if(ratesCache)return Promise.resolve(ratesCache);var ctl=typeof AbortController!=='undefined'?new AbortController():null;var to=setTimeout(function(){ctl&&ctl.abort()},12000);return fetch('https://open.er-api.com/v6/latest/USD',ctl?{signal:ctl.signal}:{}).then(function(r){clearTimeout(to);if(!r.ok)throw new Error('http');return r.json()}).then(function(j){if(!j||j.result!=='success'||!j.rates)throw new Error('bad');ratesCache=j;return j})}
T({id:'currency-converter',cat:'calc',title:'حاسبة تحويل العملات',desc:'حوّل بين العملات العربية والعالمية بأسعار صرف مباشرة من مصدر معلن، مع توضيح تاريخ آخر تحديث.',kw:'تحويل عملات سعر الصرف دولار جنيه ريال دينار currency exchange',
 fields:[{id:'amount',label:'المبلغ',type:'number',def:100},{id:'from',label:'من عملة',type:'select',options:CURS.map(function(c){return [c[0],c[0]+' - '+c[1]]}),def:'USD'},{id:'to',label:'إلى عملة',type:'select',options:CURS.map(function(c){return [c[0],c[0]+' - '+c[1]]}),def:'EGP'}],ex:{amount:100,from:'USD',to:'EGP'},btn:'حوّل',
 run:function(v){N(v,'amount');P(v,'amount');return loadRates().then(function(j){var a=j.rates[v.from],b=j.rates[v.to];if(!a||!b)throw new Error('السعر غير متاح لإحدى العملتين من المصدر حاليًا.');var rate=b/a;var res=v.amount*rate;var upd=new Date(j.time_last_update_unix*1000);var ds=upd.toISOString().replace('T',' ').slice(0,16)+' UTC';return {rows:[[f(v.amount,4)+' '+v.from,f(res,4)+' '+v.to,1],['سعر الصرف','1 '+v.from+' = '+f(rate,6)+' '+v.to],['سعر الصرف العكسي','1 '+v.to+' = '+f(1/rate,6)+' '+v.from],['آخر تحديث للأسعار',ds],['المصدر','ExchangeRate-API (open.er-api.com)']],note:'أسعار إرشادية تتحدث مرة يوميًا تقريبًا، وقد تختلف عن أسعار البنوك ومكاتب الصرف والسوق الموازية. لا تعتمد عليها في عمليات فعلية دون التحقق.'}},function(e){throw new Error('تعذّر الحصول على سعر الصرف المباشر الآن (تحقق من اتصالك بالإنترنت وحاول لاحقًا). لا نعرض أسعارًا تقديرية أو مزيفة.')})},
 how:['اكتب المبلغ المراد تحويله.','اختر العملة التي تملكها والعملة المطلوبة.','اضغط «حوّل». ستظهر النتيجة مع تاريخ آخر تحديث للسعر ومصدره.'],
 example:'تحويل 100 دولار أمريكي إلى جنيه مصري: تظهر القيمة بالسعر الحالي المنشور في المصدر مع وقت التحديث.',
 about:'أداة لتحويل المبالغ بين عشرات العملات العربية والعالمية. تُجلب الأسعار مباشرة من خدمة ExchangeRate-API المجانية وتُظهر الأداة تاريخ آخر تحديث. إذا تعذّر جلب السعر تعرض رسالة توضيحية ولا تعرض أي رقم تقديري.',
 when:'عند السفر أو الشراء من متجر أجنبي أو تقدير تحويل مبلغ لعملة أخرى، أو متابعة سعر عملة بشكل عام.',
 faqs:[['من أين تأتي أسعار الصرف؟','من خدمة ExchangeRate-API المجانية، ويظهر اسم المصدر ووقت التحديث مع كل نتيجة.'],['لماذا يختلف السعر عن البنك أو مكتب الصرف؟','أسعار المصدر عالمية وإرشادية، أما البنوك فتضيف هامشًا وعمولات، وقد يوجد سوق موازٍ بسعر مختلف.'],['ماذا يحدث إن تعذّر الاتصال؟','تظهر رسالة خطأ واضحة ولا يُعرض سعر مزيف.']],related:['percentage-calculator','vat-calculator'],note:true});
})();
